CREATE CACHED TABLE "PUBLIC"."BENEFICIARY_ACCOUNTS"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 2) NOT NULL,
    "ACCOUNT_NUMBER" CHARACTER VARYING(255),
    "ACCOUNT_REFERENCE" CHARACTER VARYING(255),
    "ACCOUNT_TYPE" ENUM('BANK', 'MPESA_PHONE', 'PAYBILL', 'RETAINED', 'TILL') NOT NULL,
    "ACTIVE" BOOLEAN NOT NULL,
    "BENEFICIARY_ID" CHARACTER VARYING(255) NOT NULL,
    "BENEFICIARY_TYPE" ENUM('BUYER', 'COUNTY', 'FARMER', 'PLATFORM') NOT NULL,
    "UPDATED_AT" TIMESTAMP(6) WITH TIME ZONE,
    "VERIFICATION_STATUS" ENUM('PENDING', 'REJECTED', 'VERIFIED') NOT NULL,
    "VERIFIED_AT" TIMESTAMP(6) WITH TIME ZONE
);   
ALTER TABLE "PUBLIC"."BENEFICIARY_ACCOUNTS" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_7" PRIMARY KEY("ID");         
