CREATE CACHED TABLE "PUBLIC"."LEDGER_ENTRIES"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "ACCOUNT_TYPE" CHARACTER VARYING(255) NOT NULL,
    "ALLOCATION_ID" BIGINT,
    "AMOUNT_CENTS" BIGINT NOT NULL,
    "CREATED_AT" TIMESTAMP(6) WITH TIME ZONE,
    "CURRENCY" CHARACTER VARYING(255),
    "DIRECTION" ENUM('CREDIT', 'DEBIT') NOT NULL,
    "ENTRY_TYPE" CHARACTER VARYING(255) NOT NULL,
    "PAYMENT_ID" BIGINT,
    "REFERENCE" CHARACTER VARYING(200)
);            
ALTER TABLE "PUBLIC"."LEDGER_ENTRIES" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_5" PRIMARY KEY("ID");               
