CREATE CACHED TABLE "PUBLIC"."ORDERS"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 5) NOT NULL,
    "CREATED_AT" TIMESTAMP(6) WITH TIME ZONE,
    "DELIVERY_ADDRESS" CHARACTER VARYING(255),
    "STATUS" ENUM('CANCELLED', 'CONFIRMED', 'DELIVERED', 'PENDING', 'SHIPPED'),
    "TOTAL" NUMERIC(38, 2),
    "BUYER_ID" BIGINT NOT NULL,
    "DELIVERY_NOTE" CHARACTER VARYING(500),
    "DELIVERY_PHONE" CHARACTER VARYING(255),
    "PAYMENT_METHOD" CHARACTER VARYING(255),
    "UPDATED_AT" TIMESTAMP(6) WITH TIME ZONE,
    "MPESA_CHECKOUT_REQUEST_ID" CHARACTER VARYING(255),
    "MPESA_RECEIPT" CHARACTER VARYING(255),
    "PAYMENT_STATUS" CHARACTER VARYING(255),
    "DELIVERED_AT" TIMESTAMP(6) WITH TIME ZONE
); 
ALTER TABLE "PUBLIC"."ORDERS" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_8" PRIMARY KEY("ID");       
