-- 5 +/- SELECT COUNT(*) FROM PUBLIC.POSTS;   
INSERT INTO "PUBLIC"."POSTS" VALUES
(1, 'ALL', U&'FarmConnect connects farmers in Trans Nzoia with buyers, county officers and agricultural services.\000a\000a\2022 Verify your identity and farm so buyers can see your produce.\000a\2022 Keep your farm records in the app: planting, harvest, expenses and income.\000a\2022 Join or create a farmer group or cooperative.\000a\2022 Check the weather advice before spraying, planting or drying your harvest.\000a\000aCounty officers will post trainings, programmes and opportunities here.', NULL, TIMESTAMP WITH TIME ZONE '2026-10-07 11:55:46.050285+00', NULL, NULL, 'Welcome to FarmConnect', 'GENERAL', 'ANNOUNCEMENT', 0, 1, NULL),
(2, 'ALL', 'A soil test tells you which nutrients and how much lime your field really needs, so you do not pay for fertiliser the crop cannot use. Collect small samples from several spots in the field, mix them, and take them to a soil-testing laboratory or ask your county extension officer how to arrange a test.', NULL, TIMESTAMP WITH TIME ZONE '2026-10-07 11:55:46.11062+00', NULL, NULL, 'Test your soil before buying fertiliser', 'SOIL_WATER', 'TIP', 0, 1, NULL),
(3, 'ALL', 'Farmers who record what they plant, spend and harvest can see which crops really make money, plan the next season and show a clear history to banks, SACCOs and buyers. Use the Records section of this app after every purchase, planting and harvest. It takes one minute and protects you from guessing.', NULL, TIMESTAMP WITH TIME ZONE '2026-10-07 11:55:46.114621+00', NULL, NULL, 'Write everything down: why farm records pay off', 'GENERAL', 'TIP', 0, 1, NULL),
(4, 'ALL', 'Maize and other cereals stored while still damp can grow mould and develop aflatoxin, which is harmful to people and animals and can make a harvest unsellable. Dry grain until it is safe for storage (about 13.5% moisture for maize), keep it off the bare floor on pallets, and use clean, dry, well-ventilated stores or hermetic bags. Ask your extension officer how to check moisture.', NULL, TIMESTAMP WITH TIME ZONE '2026-10-07 11:55:46.117617+00', NULL, NULL, 'Dry grain well before storing it', 'POST_HARVEST', 'ADVISORY', 0, 1, NULL),
(5, 'ALL', 'Always read the label, wear gloves, a mask and long clothes, never spray against the wind, and keep to the waiting period before harvest. Never reuse empty pesticide containers for food or water. Do not spray when rain is expected: check the Weather section first.', NULL, TIMESTAMP WITH TIME ZONE '2026-10-07 11:55:46.119791+00', NULL, NULL, 'Use pesticides safely', 'PESTS_DISEASES', 'TIP', 1, 1, NULL);               
